from __future__ import annotations

import json
from typing import Any

from llm_client import GeminiClient, LLMClientError
from config import DEFAULT_JUDGE_MAX_TOKENS, DEFAULT_TEMPERATURE
from utils import safe_load_json


def build_judge_prompt(input_text: str, prompt_template: str, response_text: str) -> str:
    return (
        "You are a Persian-language evaluation assistant. Review the answer generated by an LLM and score it against the input prompt. "
        "Return only valid JSON with the following keys: accuracy, completeness, clarity, relevance, overall, reasoning. "
        "Scores must be integers between 1 and 10. The reasoning should be short and explain the score in Persian if possible.\n\n"
        f"Question:\n{input_text}\n\n"
        f"Prompt template:\n{prompt_template}\n\n"
        f"Generated answer:\n{response_text}\n\n"
        "Evaluate relevance to the question, completeness of the response, clarity of language, and factual accuracy. "
        "If the response is not in Persian or is unrelated, penalize the scores accordingly."
    )


def evaluate_response(input_text: str, prompt_template: str, response_text: str, llm_model: str) -> dict[str, Any]:
    client = GeminiClient()
    prompt_text = build_judge_prompt(input_text, prompt_template, response_text)
    try:
        raw = client.generate_response(
            prompt_text,
            model=llm_model,
            max_tokens=DEFAULT_JUDGE_MAX_TOKENS,
            temperature=DEFAULT_TEMPERATURE,
        )
        judge_text = raw.get("output", "")
    except LLMClientError as exc:
        return {
            "accuracy": 1,
            "completeness": 1,
            "clarity": 1,
            "relevance": 1,
            "overall": 1,
            "reasoning": f"Judge API failure: {exc}",
        }

    score = safe_load_json(judge_text)
    score.setdefault("accuracy", 1)
    score.setdefault("completeness", 1)
    score.setdefault("clarity", 1)
    score.setdefault("relevance", 1)
    score.setdefault("overall", 1)
    score.setdefault("reasoning", "Judge response could not be parsed cleanly.")

    for key in ["accuracy", "completeness", "clarity", "relevance", "overall"]:
        try:
            score[key] = max(1, min(10, int(score.get(key, 1))))
        except (ValueError, TypeError):
            score[key] = 1

    score["reasoning"] = str(score.get("reasoning", "No reasoning provided.")).strip()
    return score
